<script>
 import {keyboardScroll} from "$lib/table-scroll.js";
 import MapNodeRegistration from "./MapNodeRegistration.svelte";
 import SystemHealth from "./SystemHealth.svelte";
 import ContactInbox from "./ContactInbox.svelte";
 import ClientEditor from "./ClientEditor.svelte";
 import PowerTrend from "./PowerTrend.svelte";
 import {usePresentation} from "$lib/presentation.svelte.js";
 import VictronOnboarding from "./VictronOnboarding.svelte";
 import ManualEnergy from "./ManualEnergy.svelte";
 import CommunityMap from "./CommunityMap.svelte";
 import SimulationNotice from "./SimulationNotice.svelte";
 import Icon from './Icon.svelte';import AdminNotice from './AdminNotice.svelte';import AdminNodeTable from './AdminNodeTable.svelte';import HistoryChart from './HistoryChart.svelte';import {formatTime,formatValue} from '$lib/energy';
 let {data:incoming,form=null}=$props();
 const presentation=usePresentation(()=>incoming);let data=$derived(presentation.data);
let search=$state('');
 const titles={health:['SYSTEM HEALTH','Your technical station.','Monitor reporting, equipment information and collection diagnostics across your network.'],overview:['OPERATIONS OVERVIEW','A clearer picture of your energy network.','Your clients, systems and connections, together in one place.'],clients:['PEOPLE & ACCESS','Energy starts with people.','Invite clients, assign their residences and manage secure access.'],nodes:['YOUR ENERGY NETWORK','Every connection, in one place.','Register systems and prepare their read-only provider connections.'],communities:['THE POWER OF UBUNTU','Build your energy communities.','Group residences and businesses before planning shared energy.'],history:['ENERGY HISTORY','Understand how energy is used.','Explore generation, household consumption and daily energy patterns.'],operations:['WORKSPACE OPERATIONS','Keep the conversation connected.','Review website enquiries and follow up with your community.'],forecasting:['DEMAND PLANNING','Turn measured history into insight.','Collect complete history, validate a baseline, then introduce machine learning.'],sharing:['SHARED ENERGY','Plan for fair access.','Version your community allocation policies before physical deployment.'],settings:['WORKSPACE SETTINGS','A platform you can manage.','Configure operational thresholds, support and administrator access.'],activity:['ACCOUNTABILITY','Every change leaves a trace.','Review administrative actions and their recorded context.']};
 let section=$derived(data.section||'overview');let title=$derived(titles[section]);let clients=$derived(data.clients.filter(c=>c.role==='client'));let filteredClients=$derived(clients.filter(c=>(c.full_name+' '+c.email).toLowerCase().includes(search.toLowerCase())));let pending=$derived(data.nodes.filter(n=>!data.connections.find(c=>c.node_id===n.id)?.verified_at&&!data.connections.find(c=>c.node_id===n.id)?.simulated));let activeAlerts=$derived(data.alerts.filter(a=>!a.acknowledged));
 const href=s=>data.preview?'/admin-preview?view='+s:s==='overview'?'/admin':'/admin/'+s;
 const nodeHref=id=>data.preview?href('nodes'):'/admin/nodes/'+id;
 const name=id=>data.nodes.find(n=>n.id===id)?.display_name||'Node';
 const date=value=>value?new Intl.DateTimeFormat('en-ZW',{timeZone:'Africa/Harare',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Not yet';
 let history=$derived.by(()=>{const values={solar:[],consumption:[],totals:{}};for(const metric of ['solar','consumption']){values[metric]=(data.intervals||[]).filter(r=>r.metric===metric).map(r=>({time:r.interval_start,value:Number(r.energy_kwh)}));values.totals[metric]=values[metric].length?values[metric].reduce((s,p)=>s+p.value,0):null;}return values;});
 function download(){const rows=['interval_start,interval_end,metric,resolution,energy_kwh,data_source',...(data.intervals||[]).map(r=>[r.interval_start,r.interval_end,r.metric,r.resolution,r.energy_kwh,r.simulated?'simulated':'provider'].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=data.simulated?'gridubuntu-simulated-energy.csv':'gridubuntu-measured-energy.csv';anchor.click();URL.revokeObjectURL(url);}
</script>
<svelte:head><title>{title[0]} | GridUbuntu</title></svelte:head>
{#if data.simulationEnabled}<SimulationNotice/>{/if}
<div class="admin-page-heading"><div><span class="admin-eyebrow">{title[0]}</span><h1>{title[1]}</h1><p>{title[2]}</p></div><span class="admin-workspace"><i></i>{data.preview?'Sample pilot':'Pilot workspace'}</span></div>
<AdminNotice {form}/>
{#if section==='overview'}
 <div class="admin-stat-strip"><a href={href('nodes')}><span>Registered nodes</span><strong>{data.nodes.length}</strong><small>Residences & businesses <b>↗</b></small></a><a href={href('clients')}><span>Pilot clients</span><strong>{clients.length}</strong><small>{clients.filter(c=>c.active).length} with active access <b>↗</b></small></a><a href={href('nodes')}><span>Verified connections</span><strong>{data.connections.filter(c=>c.active&&c.verified_at).length}<small> / {data.nodes.length}</small></strong><small>{pending.length} awaiting setup <b>↗</b></small></a><a href={href('operations')}><span>Open alerts</span><strong>{activeAlerts.length}</strong><small>From commissioned systems <b>↗</b></small></a></div>
 <div class="admin-overview-grid"><section class="admin-panel admin-next-step"><div class="admin-panel-head"><div><span class="admin-eyebrow">MAKE THE NEXT CONNECTION</span><h2>{data.simulationEnabled?'Your energy workspace is ready.':pending.length?'Your next step is ready.':'Your connections are verified.'}</h2></div><Icon name="sun" size={30}/></div>{#if pending.length}{@const first=pending[0]}<p>Finish linking <strong>{first.display_name}</strong> to its SunSynk installation. Your token is stored securely; a selected and verified site unlocks accurate client readings.</p><ol class="admin-step-list"><li><span>01</span> Register the residence and client</li><li><span>02</span> Select the correct provider installation</li><li><span>03</span> Test, compare with VRM and verify</li></ol><a class="admin-button" href={nodeHref(first.id)+'?tab=connection'}>Continue connection setup <span>→</span></a>{:else}<p>{data.simulationEnabled?'Open Energy nodes to explore power production, household use, battery storage and energy history.':'Review collection health and measured history as your network grows.'}</p><a class="admin-button" href={href(data.simulationEnabled?'nodes':'operations')}>{data.simulationEnabled?'Explore energy nodes':'Review operations'} →</a>{/if}</section><section class="admin-panel admin-today-panel"><span class="admin-eyebrow">A TRUSTWORTHY ENERGY PICTURE</span><h2>Measure first.<br/>Share with confidence.</h2><p>Readings appear after connection verification. Missing data stays missing, and every value keeps its reporting time.</p><div><Icon name="lock" size={20}/><span>SunSynk integration is read only</span></div><div><Icon name="account" size={20}/><span>Clients see assigned residences</span></div><div><Icon name="history" size={20}/><span>Administration is recorded in the audit trail</span></div></section></div>
 <AdminNodeTable {data} compact/>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">LATEST WORKSPACE CHANGES</span><h2>Recent activity</h2></div><a class="admin-text-link" href={href('activity')}>Full audit trail →</a></div>{@render activityTable(data.activity||[])}</section>
{:else if section==='nodes'}
 <VictronOnboarding {data}/><MapNodeRegistration {data}/>
 <details class="admin-create"><summary><span>Register an unconnected node</span><small>A GridUbuntu reference is generated automatically.</small></summary><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="node.save"/><label>Residence or business name<input name="display_name" required minlength="2" maxlength="120" placeholder="e.g. Genius Mukichi Residence"/></label><label>Location label<input name="location_label" required maxlength="120" placeholder="Town or community, Zimbabwe"/></label><label>Community<select name="community_id"><option value="">Assign later</option>{#each data.communities as c}<option value={c.id}>{c.name}</option>{/each}</select></label><button class="admin-button" disabled={data.preview}>Register node →</button></form></details><AdminNodeTable {data}/>
{:else if section==='clients'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">INVITATION ONLY</span><h2>Invite a client</h2></div><span class="admin-status">Private activation link</span></div><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="client.invite"/><label>Full name<input name="full_name" required maxlength="120" autocomplete="name"/></label><label>Email address<input name="email" type="email" required maxlength="254" autocomplete="email"/></label><label>Assign residence<select name="node_id"><option value="">Assign later</option>{#each data.nodes as n}<option value={n.id}>{n.display_name}</option>{/each}</select></label><button class="admin-button" disabled={data.preview}>Create invitation link →</button></form><p class="admin-help">Creates an invited account and a private, expiring activation link. No email is sent automatically. For an activated account, a recovery link is created instead.</p></section>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">YOUR PILOT CLIENTS</span><h2>Client directory</h2></div><label class="admin-search"><span class="sr-only">Search clients</span><input type="search" bind:value={search} placeholder="Search name or email"/></label></div><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Name & email</th><th>Assigned residences</th><th>Account state</th><th>Manage access</th></tr></thead><tbody>{#each filteredClients as client}<tr><td><strong>{client.full_name}</strong><small>{client.email}</small></td><td>{data.memberships.filter(m=>m.user_id===client.id).map(m=>name(m.node_id)).join(', ')||'Not yet assigned'}</td><td><span class="admin-status" class:good={client.active&&client.email_confirmed_at}>{!client.active?'Access revoked':client.email_confirmed_at?'Activated':'Invitation pending'}</span></td><td><ClientEditor {client} preview={data.preview} nodes={data.nodes} memberships={data.memberships} maps={data.maps}/></td></tr>{/each}{#if !filteredClients.length}<tr><td colspan="4"><div class="admin-empty">No matching clients. Create an invitation to get started.</div></td></tr>{/if}</tbody></table></div></section>
{:else if section==='communities'}
 <CommunityMap {data}/><MapNodeRegistration {data}/>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">COMMUNITY DIRECTORY</span><h2>Create a community</h2></div></div><form method="POST" class="admin-inline-form"><input type="hidden" name="operation" value="community.save"/><label>Community name<input name="name" required minlength="2" maxlength="120" placeholder="Community or pilot group"/></label><button class="admin-button" disabled={data.preview}>Create community →</button></form></section><div class="admin-community-grid">{#each data.communities as community}<section class="admin-panel"><Icon name="home" size={26}/><h2>{community.name}</h2><p class="admin-help">{data.nodes.filter(n=>n.community_id===community.id).length} registered nodes</p><ul class="admin-simple-list">{#each data.nodes.filter(n=>n.community_id===community.id) as node}<li><a href={nodeHref(node.id)}>{node.display_name} →</a></li>{/each}</ul><details class="admin-row-details"><summary>Edit name</summary><form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="community.save"/><input type="hidden" name="community_id" value={community.id}/><label>Community name<input name="name" value={community.name} required maxlength="120"/></label><button class="admin-button secondary" disabled={data.preview}>Save name</button></form></details></section>{/each}{#if !data.communities.length}<section class="admin-panel admin-empty"><Icon name="home" size={30}/><strong>No communities registered yet</strong><p>Create a community, then assign nodes from their detail pages.</p></section>{/if}</div>
{:else if section==='health'}
 <SystemHealth {data}/>
{:else if section==='history'}
 {#if data.simulated}<PowerTrend reportedAt={data.snapshot?.reportedAt||data.snapshots.find(s=>s.node_id===data.node?.id)?.reported_at}/>{/if}
 {@render nodeSelector()}<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">{data.node?.reference||'NO NODE SELECTED'}</span><h2>{data.node?.display_name||'Select an energy node'}</h2></div><button class="admin-button secondary" onclick={download} disabled={!data.intervals?.length}>Export CSV ↓</button></div><div class="admin-range-tabs">{#each [['today','Today'],['7d','7 days'],['30d','30 days']] as [value,label]}<a class:active={data.range===value} href={data.preview?href('history'):`/admin/history?node=${data.node?.id||''}&range=${value}`}>{label}</a>{/each}</div><HistoryChart {history} range={data.range||'7d'}/><p class="admin-help">{data.simulated?'The current period is still in progress.':'Persisted provider measurements only.'} Totals and visible bars may be partial when intervals are missing.</p></section>
{:else if section==='operations'}
 <ContactInbox enquiries={data.enquiries||[]} preview={data.preview}/>
 <section class="admin-panel"><span class="admin-eyebrow">TECHNICAL MONITORING</span><h2>System diagnostics have a new home.</h2><p class="admin-help">Open System Health for node alerts, collection runs, equipment information and energy history.</p><a class="admin-button secondary" href={href('health')}>Open System Health ?</a></section>
{:else if section==='forecasting'}
 {@render nodeSelector()}<div class="admin-two-column"><section class="admin-panel"><span class="admin-eyebrow">DATA READINESS</span><h2>{data.node?.display_name||'Select a node'}</h2><div class="admin-readiness"><strong>{data.completeDays||0}<small> / 8 days</small></strong><span>Complete historical days available</span></div><p class="admin-help">A complete day needs 24 measured hourly consumption intervals. Seven days train the baseline; a separate day validates it. Recent complete data is also required.</p><form method="POST"><input type="hidden" name="operation" value="forecast.run"/><input type="hidden" name="node_id" value={data.node?.id||''}/><button class="admin-button" disabled={data.preview||!data.node||(data.completeDays||0)<8}>Generate validated baseline →</button></form></section><section class="admin-panel admin-today-panel"><span class="admin-eyebrow">START WITH AN HONEST BASELINE</span><h2>Learn the daily rhythm.</h2><p>The first model takes the median consumption for each hour across seven complete days. Its validation error is measured on a held-out day.</p><p>No machine-learning model or weather adjustment is claimed here. These come after the measured history is sufficient.</p></section></div>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">SAVED FORECAST RUNS</span><h2>Prediction & validation</h2></div></div>{#each data.forecasts||[] as forecast}<details class="admin-forecast"><summary><strong>Hourly median baseline</strong><span>{date(forecast.generated_at)} · MAE {formatValue(forecast.metrics.validation_mae_kwh,'kWh',3)}</span></summary><p class="admin-help">Validation day: {forecast.metrics.validation_day}. Hourly error is measured in kWh. Predictions have no weather features or calibrated uncertainty interval.</p><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Predicted interval · CAT</th><th>Consumption estimate</th></tr></thead><tbody>{#each forecast.predictions as p}<tr><td>{date(p.time)}</td><td>{formatValue(p.consumption_kwh,'kWh',3)}</td></tr>{/each}</tbody></table></div></details>{/each}{#if !data.forecasts?.length}<div class="admin-empty"><Icon name="history" size={30}/><strong>No forecast runs yet</strong><p>Measured history and a validation result will appear before predictions are used.</p></div>{/if}</section>
{:else if section==='sharing'}
 <ManualEnergy {data}/>
 <div class="admin-notice"><strong>Planning policies · no hardware enforcement</strong><p>These versioned drafts document intended allocations. Accurate contribution accounting needs household meters, an energy ledger and a separately reviewed control system.</p></div><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">VERSIONED COMMUNITY POLICY</span><h2>Create an allocation draft</h2></div></div><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="policy.save"/><label>Community<select name="community_id" required><option value="">Select community</option>{#each data.communities as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Allocation approach<select name="model"><option value="equal_share">Equal share</option><option value="essential_first">Essential loads first</option></select></label><label>Battery reserve (%)<input name="battery_reserve" type="number" min="0" max="100" step="1" value="20" required/></label><label>Household power limit (kW)<input name="household_limit_kw" type="number" min="0.01" max="1000" step="0.01" value="1" required/></label><label class="admin-span-two">Policy notes<textarea name="notes" maxlength="1000" rows="3" placeholder="Describe essential loads, exceptions and the metering needed."></textarea></label><button class="admin-button" disabled={data.preview||!data.communities.length}>Save new draft version →</button></form></section><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">POLICY HISTORY</span><h2>Saved versions</h2></div></div>{#each data.policies||[] as policy}<div class="admin-policy-row"><div><strong>{data.communities.find(c=>c.id===policy.community_id)?.name||'Community'} · Version {policy.version}</strong><p>{policy.model==='equal_share'?'Equal share':'Essential loads first'} · {policy.battery_reserve}% reserve · {policy.household_limit_kw} kW household limit</p><small>{policy.notes||'No additional notes'} · {date(policy.created_at)}</small></div><details class="admin-row-details"><summary>Edit as a new version</summary><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="policy.save"/><input type="hidden" name="community_id" value={policy.community_id}/><label>Approach<select name="model" value={policy.model}><option value="equal_share">Equal share</option><option value="essential_first">Essential loads first</option></select></label><label>Reserve (%)<input name="battery_reserve" type="number" min="0" max="100" value={policy.battery_reserve} required/></label><label>Power limit (kW)<input name="household_limit_kw" type="number" min="0.01" max="1000" step="0.01" value={policy.household_limit_kw} required/></label><label>Notes<textarea name="notes" maxlength="1000">{policy.notes}</textarea></label><div class="admin-form-actions admin-span-two"><button class="admin-button secondary" disabled={data.preview}>Save revised policy version</button></div></form></details></div>{/each}{#if !data.policies?.length}<div class="admin-empty">No allocation drafts yet. Create a community to begin planning.</div>{/if}</section>
{:else if section==='settings'}
 {#if data.collector}<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">UNATTENDED DATA COLLECTION</span><h2>Collection scheduler</h2></div><span class="admin-status" class:good={data.collector.enabled}>{data.collector.enabled?'Enabled':'Not enabled'}</span></div><div class="admin-node-summary"><div><span>Schedule</span><strong>Every 15 minutes</strong></div><div><span>Last request enqueued</span><strong>{date(data.collector.last_enqueued_at)}</strong></div><div><span>Last completed HTTP result</span><strong>{data.collector.last_http_status||'Not received yet'}</strong></div><div><span>Eligible systems</span><strong>Active, verified connections</strong></div></div><p class="admin-help">The scheduler requests collection while the portal is closed. An HTTP result confirms endpoint access; node-level outcomes appear under System Health. No energy readings are collected for unverified systems. Each run handles up to 10 nodes, with three provider connections processed concurrently.</p><form method="POST"><input type="hidden" name="operation" value="collector.toggle"/><input type="hidden" name="enabled" value={data.collector.enabled?'false':'true'}/><button class="admin-button secondary" disabled={data.preview||!data.collector.job_id}>{data.collector.enabled?'Pause schedule':'Enable schedule'}</button></form></section>{/if}

 <div class="admin-two-column"><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">OPERATING PREFERENCES</span><h2>Support & battery alerts</h2></div></div><form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="settings.save"/><label>Support email<input type="email" name="support_email" value={data.settings.support_email} required maxlength="254"/></label><label>Low battery warning below (%)<input type="number" name="low_battery_percent" min="1" max="99" step="1" value={data.settings.low_battery_percent} required/></label><button class="admin-button" disabled={data.preview}>Save settings</button></form><p class="admin-help">Battery warnings use the latest measured state of charge. Delayed readings are identified separately after 15 minutes.</p></section><section class="admin-panel"><span class="admin-eyebrow">COLLECTION & SECURITY</span><h2>Designed for measured data.</h2><ul class="admin-security-list"><li>Provider credentials are encrypted server-side.</li><li>Every mutation requires an active administrator.</li><li>Clients have no browser write access.</li><li>Verified nodes can be collected manually or by the protected scheduler.</li><li>Collection never sends equipment-control commands.</li></ul><p class="admin-help">Connection verification and scheduled collection are separate. Check operational run history to confirm data is arriving.</p></section></div>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">TRUSTED WORKSPACE ACCESS</span><h2>Administrator permissions</h2></div><span class="admin-status">{data.clients.filter(c=>c.role==='admin'&&c.active).length} active administrators</span></div><p class="admin-help">Create an invited account in Clients & access first, then grant its role here. Full administrators can manage clients, credentials and permissions. Your own access cannot be changed from your session.</p><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="admin.access"/><label>Invited account<select name="user_id" required><option value="">Select account</option>{#each data.clients.filter(c=>c.id!==data.profile.id) as c}<option value={c.id}>{c.full_name} · {c.email} · {c.role}</option>{/each}</select></label><label>Role<select name="role"><option value="client">Client — assigned residences only</option><option value="admin">Administrator — full operations access</option></select></label><label>Account access<select name="active"><option value="true">Active</option><option value="false">Revoked</option></select></label><label class="admin-checkbox"><input type="checkbox" name="confirmed" value="yes" required/>I confirm this permission change.</label><button class="admin-button" disabled={data.preview}>Update permissions</button></form><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Administrator</th><th>Email</th><th>Access</th></tr></thead><tbody>{#each data.clients.filter(c=>c.role==='admin') as c}<tr><td>{c.full_name}</td><td>{c.email}</td><td>{c.active?'Active':'Revoked'}</td></tr>{/each}</tbody></table></div></section>
{:else if section==='activity'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">MOST RECENT 100 EVENTS</span><h2>Administrative audit trail</h2></div><span class="admin-status">Server-recorded</span></div>{@render activityTable(data.activity||[])}</section>
{/if}

{#snippet nodeSelector()}<form method="GET" class="admin-node-selector"><label>Energy node<select name="node" value={data.node?.id||''}><option value="">Select a node</option>{#each data.nodes as n}<option value={n.id}>{n.reference} · {n.display_name}</option>{/each}</select></label><button class="admin-button secondary" disabled={data.preview}>View node →</button></form>{/snippet}
{#snippet activityTable(events)}<div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Time · CAT</th><th>Action</th><th>Administrator</th><th>Node / context</th></tr></thead><tbody>{#each events as event}<tr><td>{date(event.created_at)}</td><td><strong>{event.action.replaceAll('.',' / ').replaceAll('_',' ')}</strong></td><td>{data.clients.find(c=>c.id===event.actor_id)?.full_name||'System / setup'}</td><td>{event.node_id?name(event.node_id):'Workspace'}{#if Object.keys(event.details||{}).length}<details><summary>Details</summary><dl class="admin-audit-details">{#each Object.entries(event.details) as [key,value]}<div><dt>{key.replaceAll('_',' ')}</dt><dd>{String(value??'—')}</dd></div>{/each}</dl></details>{/if}</td></tr>{/each}{#if !events.length}<tr><td colspan="4"><div class="admin-empty">No administrative events recorded yet.</div></td></tr>{/if}</tbody></table></div>{/snippet}
